import type { Booking } from '../lib/booking.ts';

// Turn a row read from storage into a Booking — checked, not cast.
export function toBooking(row: unknown): Booking {
  if (typeof row !== 'object' || row === null) throw new TypeError('row must be an object');
  if (!('lab' in row) || typeof row.lab !== 'string') throw new TypeError('lab must be a string');
  if (!('start' in row) || typeof row.start !== 'string') throw new TypeError('start must be a string');
  if (!('end' in row) || typeof row.end !== 'string') throw new TypeError('end must be a string');
  if (!('minutes' in row) || typeof row.minutes !== 'number') throw new TypeError('minutes must be a number');
  if (!('status' in row) || (row.status !== 'PENDING' && row.status !== 'CONFIRMED')) {
    throw new TypeError('status must be PENDING or CONFIRMED');
  }
  // Every field is narrowed now, so this object literal is a real Booking.
  return { lab: row.lab, start: row.start, end: row.end, minutes: row.minutes, status: row.status };
}

